<template>
  <b-container fluid class="py-3">
    <b-row>
      <b-col lg="8" md="7">
        <b-card no-body class="shadow-sm border-0">
          <b-card-header
            class="bg-white d-flex justify-content-between align-items-center py-3"
          >
            <h5 class="mb-0 text-dark">
              <b-icon icon="people-fill" class="mr-2 text-primary"></b-icon>
              Colaboradores
              <b-badge variant="light" pill class="border ml-2">{{
                users.length
              }}</b-badge>
            </h5>
            <b-button
              size="sm"
              variant="outline-secondary"
              pill
              @click="refreshUsers"
              :disabled="isLoading"
            >
              <b-icon
                icon="arrow-clockwise"
                :animation="isLoading ? 'spin' : ''"
              ></b-icon>
              Atualizar
            </b-button>
          </b-card-header>

          <b-overlay :show="isLoading" rounded="sm" opacity="0.6">
            <div class="table-responsive">
              <table class="table table-hover mb-0">
                <thead class="thead-light">
                  <tr>
                    <th>Nome Completo</th>
                    <th>Perfil</th>
                    <th>Status</th>
                    <th class="text-center">Ações</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-if="users.length === 0">
                    <td colspan="4" class="text-center py-5 text-muted">
                      Nenhum usuário cadastrado.
                    </td>
                  </tr>
                  <tr
                    v-for="u in users"
                    :key="u.id"
                    :class="{ 'table-warning': userUpdationId === u.id }"
                  >
                    <td class="align-middle font-weight-bold">{{ u.name }}</td>
                    <td class="align-middle">
                      <b-badge variant="light" class="border">{{
                        convertRole(u.userRole)
                      }}</b-badge>
                    </td>
                    <td class="align-middle">
                      <b-badge
                        :variant="u.status === 1 ? 'success' : 'danger'"
                        pill
                      >
                        {{ u.status === 1 ? "Ativo" : "Inativo" }}
                      </b-badge>
                    </td>
                    <td class="text-center">
                      <b-button-group size="sm">
                        <b-button
                          variant="link"
                          @click="updateUser(u)"
                          title="Editar"
                        >
                          <b-icon
                            icon="pencil-square"
                            variant="primary"
                          ></b-icon>
                        </b-button>
                        <b-button
                          variant="link"
                          @click="decidedToReset(u)"
                          title="Resetar Senha"
                        >
                          <b-icon icon="unlock-fill" variant="warning"></b-icon>
                        </b-button>
                        <b-button
                          variant="link"
                          @click="deleteUser(u)"
                          title="Excluir"
                        >
                          <b-icon icon="trash" variant="danger"></b-icon>
                        </b-button>
                      </b-button-group>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </b-overlay>
        </b-card>
      </b-col>

      <b-col lg="4" md="5">
        <b-card
          shadow="sm"
          :border-variant="userUpdationId !== 0 ? 'warning' : ''"
        >
          <h6 class="font-weight-bold mb-4">
            <b-icon
              :icon="
                userUpdationId === 0 ? 'person-plus-fill' : 'pencil-square'
              "
            ></b-icon>
            {{ userUpdationId === 0 ? "Novo Usuário" : "Editar Colaborador" }}
          </h6>

          <b-form @submit.prevent="saveUser">
            <b-form-group
              label="Nome Completo"
              label-class="small font-weight-bold"
            >
              <b-form-input
                v-model="form.name"
                size="sm"
                placeholder="Ex: João Silva"
                required
              ></b-form-input>
            </b-form-group>

            <b-form-group
              label="Telemóvel (12 dígitos)"
              label-class="small font-weight-bold"
            >
              <b-form-input
                v-model="form.phone"
                size="sm"
                placeholder="258XXXXXXXXX"
                required
              ></b-form-input>
            </b-form-group>

            <b-form-group label="E-mail" label-class="small font-weight-bold">
              <b-form-input
                v-model="form.email"
                type="email"
                size="sm"
                placeholder="email@empresa.com"
                required
              ></b-form-input>
            </b-form-group>

            <b-alert
              show
              variant="info"
              class="py-2"
              v-if="userUpdationId === 0"
            >
              <small class="d-block font-weight-bold">Senha gerada:</small>
              <code>{{ form.password }}</code>
            </b-alert>

            <b-row>
              <b-col md="6">
                <b-form-group
                  label="Perfil"
                  label-class="small font-weight-bold"
                >
                  <b-form-select
                    v-model="form.userRole"
                    :options="roles"
                    size="sm"
                    required
                  ></b-form-select>
                </b-form-group>
              </b-col>
              <b-col md="6">
                <b-form-group
                  label="Status"
                  label-class="small font-weight-bold"
                >
                  <b-form-select
                    v-model="form.status"
                    :options="userStatus"
                    size="sm"
                    required
                  ></b-form-select>
                </b-form-group>
              </b-col>
            </b-row>

            <hr />

            <div class="d-flex justify-content-between">
              <b-button
                variant="light"
                size="sm"
                @click="resetFields"
                :disabled="isLoading"
                >Cancelar</b-button
              >
              <b-button
                type="submit"
                variant="success"
                size="sm"
                :disabled="isLoading"
              >
                <b-spinner small v-if="isLoading" class="mr-1"></b-spinner>
                {{ userUpdationId === 0 ? "Cadastrar" : "Salvar" }}
              </b-button>
            </div>
          </b-form>
        </b-card>
      </b-col>
    </b-row>

    <b-modal
      ref="delete-user"
      title="Confirmar Exclusão"
      centered
      header-bg-variant="danger"
      header-text-variant="white"
    >
      <p>
        Deseja realmente excluir o acesso de
        <strong>{{ selectedUser.name }}</strong
        >?
      </p>
      <template #modal-footer="{ cancel }">
        <b-button size="sm" variant="light" @click="cancel()">Voltar</b-button>
        <b-button size="sm" variant="danger" @click="decidedToDelete"
          >Confirmar Exclusão</b-button
        >
      </template>
    </b-modal>

    <b-modal ref="reset-user" title="Redefinir Senha" centered>
      <p>
        Uma nova senha será gerada para
        <strong>{{ selectedUserUpdate.name }}</strong
        >.
      </p>
      <template #modal-footer="{ cancel }">
        <b-button size="sm" variant="light" @click="cancel()"
          >Cancelar</b-button
        >
        <b-button size="sm" variant="success" @click="updateUserPassword"
          >Redefinir Agora</b-button
        >
      </template>
    </b-modal>
  </b-container>
</template>

<script>
// O script permanece o mesmo do anterior, garantindo que os métodos
// saveUser, updateUser e decidedToDelete estejam presentes.
import axios from "axios";
import { mapGetters } from "vuex";
// import logs from "@/utils/logs";

export default {
  name: "UserComponent",
  data: () => ({
    form: {
      name: "",
      phone: "258",
      email: "",
      password: "",
      userRole: 3,
      status: 1,
      companyId: "",
    },
    roles: [
      { text: "Admin", value: 1 },
      { text: "Atendimento", value: 2 },
      { text: "Gestor", value: 3 },
    ],
    userStatus: [
      { text: "Ativo", value: 1 },
      { text: "Inativo", value: 0 },
    ],
    userDeletionId: 0,
    userUpdationId: 0,
    selectedUser: {},
    selectedUserUpdate: {},
  }),
  computed: { ...mapGetters(["isLoading", "user", "company", "users"]) },
  created() {
    this.refreshUsers();
    this.generateNewPassword();
  },
  methods: {
    refreshUsers() {
      this.$store.dispatch("getAllUsers", this.company.id);
    },
    generateNewPassword() {
      this.form.password = Math.floor(
        100000 + Math.random() * 900000
      ).toString();
    },
    async saveUser() {
      this.$store.commit("LOADING_STATUS", true);
      const isUpdate = this.userUpdationId !== 0;
      const url = isUpdate ? `/api/users/${this.userUpdationId}` : "/api/users";
      const method = isUpdate ? "put" : "post";
      try {
        const { data } = await axios[method](url, {
          ...this.form,
          companyId: this.company.id,
        });
        if (data.success) {
          this.refreshUsers();
          this.resetFields();
        }
      } catch (err) {
        console.error(err);
      } finally {
        this.$store.commit("LOADING_STATUS", false);
      }
    },
    updateUser(user) {
      this.userUpdationId = user.id;
      this.form = { ...user };
    },
    async decidedToDelete() {
      await axios.delete(`/api/users/${this.userDeletionId}`);
      this.refreshUsers();
      this.$refs["delete-user"].hide();
    },
    resetFields() {
      this.userUpdationId = 0;
      this.form = {
        name: "",
        phone: "258",
        email: "",
        userRole: 3,
        status: 1,
        companyId: this.company.id,
      };
      this.generateNewPassword();
    },
    convertRole(role) {
      const roleMap = { 1: "Admin", 2: "Atendimento", 3: "Gestor" };
      return roleMap[role] || "N/A";
    },
    deleteUser(user) {
      this.userDeletionId = user.id;
      this.selectedUser = user;
      this.$refs["delete-user"].show();
    },
    decidedToReset(user) {
      this.selectedUserUpdate = user;
      this.$refs["reset-user"].show();
    },
    updateUserPassword() {
      /* Lógica de reset */
    },
  },
};
</script>
