<template>
  <b-container fluid class="py-3">
    <b-row>
      <b-col lg="8" md="7">
        <b-card no-body shadow="sm">
          <template #header>
            <div class="d-flex justify-content-between align-items-center">
              <h5 class="mb-0">
                <b-icon icon="percent" class="mr-2"></b-icon>
                Tipos de Financiamento ({{ interestRates.length }})
              </h5>
              <b-button
                size="sm"
                variant="outline-secondary"
                pill
                @click="getAllRates"
                :disabled="isLoading"
              >
                <b-icon
                  icon="arrow-clockwise"
                  :animation="isLoading ? 'spin' : ''"
                ></b-icon>
                Atualizar
              </b-button>
            </div>
          </template>

          <b-overlay :show="isLoading" rounded="sm" opacity="0.6">
            <div class="table-responsive">
              <table class="table table-hover mb-0">
                <thead class="thead-light">
                  <tr>
                    <th>Tipo de Crédito</th>
                    <th>Juros (%)</th>
                    <th>Taxa Administrativa</th>
                    <th class="text-center">Ações</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-if="interestRates.length === 0">
                    <td colspan="4" class="text-center py-4 text-muted">
                      Nenhuma taxa cadastrada.
                    </td>
                  </tr>
                  <tr
                    v-for="tax in interestRates"
                    :key="tax.id"
                    :class="{ 'table-primary': form.id === tax.id }"
                  >
                    <td class="align-middle font-weight-bold">
                      {{ tax.name }}
                    </td>
                    <td class="align-middle">
                      {{ (tax.tax * 100).toFixed(2) }}%
                    </td>
                    <td
                      class="align-middle"
                      v-money-format="tax.administrativeFee"
                    ></td>
                    <td class="text-center">
                      <b-button-group size="sm">
                        <b-button
                          variant="link"
                          @click="editTax(tax)"
                          title="Editar"
                        >
                          <b-icon
                            icon="pencil-square"
                            variant="primary"
                          ></b-icon>
                        </b-button>
                        <b-button
                          variant="link"
                          @click="confirmDelete(tax)"
                          title="Excluir"
                        >
                          <b-icon icon="trash" variant="danger"></b-icon>
                        </b-button>
                      </b-button-group>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </b-overlay>
        </b-card>
      </b-col>

      <b-col lg="4" md="5">
        <b-card shadow="sm" :border-variant="form.id !== 0 ? 'warning' : ''">
          <h5 class="card-title mb-4">
            <b-icon
              :icon="form.id === 0 ? 'plus-circle' : 'pencil-square'"
            ></b-icon>
            {{ form.id === 0 ? "Nova Taxa" : "Editar Taxa" }}
          </h5>

          <b-form @submit.prevent="saveTax">
            <b-form-group label="Nome do Crédito">
              <b-form-input
                v-model="form.name"
                placeholder="Ex: Crédito Pessoal"
                required
                size="sm"
              ></b-form-input>
            </b-form-group>

            <b-form-group label="Taxa Administrativa">
              <b-form-input
                v-model.number="form.administrativeFee"
                type="number"
                step="0.01"
                required
                size="sm"
              ></b-form-input>
            </b-form-group>

            <b-form-group
              label="Juros Mensais (%)"
              description="Valor entre 1 e 30"
            >
              <b-form-input
                v-model.number="displayTax"
                type="number"
                step="0.1"
                min="1"
                max="30"
                required
                size="sm"
              ></b-form-input>
            </b-form-group>

            <hr />

            <div class="d-flex justify-content-between">
              <b-button
                variant="light"
                size="sm"
                @click="resetFields"
                :disabled="isLoading"
              >
                Cancelar
              </b-button>
              <b-button
                type="submit"
                variant="success"
                size="sm"
                :disabled="isLoading"
              >
                <b-spinner small v-if="isLoading" class="mr-1"></b-spinner>
                {{ form.id === 0 ? "Cadastrar" : "Salvar Alterações" }}
              </b-button>
            </div>
          </b-form>
        </b-card>
      </b-col>
    </b-row>

    <b-modal
      ref="delete-modal"
      title="Confirmar Exclusão"
      header-bg-variant="danger"
      header-text-variant="white"
      centered
      @ok="handleDelete"
    >
      <p>
        Tem certeza que deseja excluir a taxa
        <strong>{{ selectedTax?.name }}</strong
        >?
      </p>
      <template #modal-footer="{ ok, cancel }">
        <b-button size="sm" variant="outline-secondary" @click="cancel()"
          >Voltar</b-button
        >
        <b-button size="sm" variant="danger" @click="ok()"
          >Confirmar Exclusão</b-button
        >
      </template>
    </b-modal>
  </b-container>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import logs from "@/utils/logs";

export default {
  name: "InterestRateComponent",

  data: () => ({
    form: {
      id: 0,
      name: "",
      tax: 0.1, // Armazenado como decimal (0.1 = 10%)
      administrativeFee: 0.0,
    },
    selectedTax: null,
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "company", "interestRates"]),

    // Getter/Setter para facilitar a manipulação da porcentagem no input
    displayTax: {
      get() {
        return (this.form.tax * 100).toFixed(1);
      },
      set(val) {
        this.form.tax = val / 100;
      },
    },
  },

  methods: {
    getAllRates() {
      this.$store.dispatch("getAllRates", this.company.id);
    },

    resetFields() {
      this.form = { id: 0, name: "", tax: 0.1, administrativeFee: 0.0 };
      this.selectedTax = null;
    },

    editTax(tax) {
      this.form = { ...tax };
      window.scrollTo({ top: 0, behavior: "smooth" });
    },

    async saveTax() {
      if (this.form.name.length < 3) {
        return this.showToast("Aviso", "warning", "Nome muito curto.");
      }

      const isUpdate = this.form.id !== 0;
      const url = isUpdate ? `/api/rate/${this.form.id}` : "/api/rate";
      const method = isUpdate ? "put" : "post";

      const payload = {
        ...this.form,
        companyId: this.company.id,
      };

      try {
        this.$store.commit("LOADING_STATUS", true);
        const { data } = await axios[method](url, payload);

        if (data.success) {
          this.showToast(
            "Sucesso",
            "success",
            isUpdate ? "Taxa atualizada!" : "Taxa cadastrada!"
          );
          this.logAction(isUpdate ? "Atualização" : "Cadastro");
          this.getAllRates();
          this.resetFields();
        } else {
          this.showToast("Erro", "danger", data.message);
        }
      } catch (err) {
        this.showToast("Erro de Conexão", "danger", err.message);
      } finally {
        this.$store.commit("LOADING_STATUS", false);
      }
    },

    confirmDelete(tax) {
      this.selectedTax = tax;
      this.$refs["delete-modal"].show();
    },

    async handleDelete() {
      try {
        this.$store.commit("LOADING_STATUS", true);
        const { data } = await axios.delete(`/api/rate/${this.selectedTax.id}`);

        if (data.success) {
          this.showToast("Excluído", "success", "Taxa removida com sucesso.");
          this.logAction("Exclusão");
          this.getAllRates();
        }
      } catch (err) {
        this.showToast("Erro", "danger", err.message);
      } finally {
        this.$store.commit("LOADING_STATUS", false);
      }
    },

    logAction(actionType) {
      const logsParams = logs(
        this.user,
        `${actionType}: ${this.form.name || this.selectedTax.name}`,
        `Gestão de Taxas - ${actionType}`
      );
      this.$store.dispatch("addLog", logsParams);
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(msg, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 4000,
      });
    },
  },
};
</script>

<style scoped>
.table th {
  border-top: none;
}
.card {
  border-radius: 8px;
}
.table-primary td {
  background-color: rgba(0, 123, 255, 0.1);
}
</style>
