<template>
  <div class="settings-view bg-light min-vh-100">
    <NavBarVue />
    <b-container fluid class="py-4">
      <b-row>
        <b-col lg="3" md="4" class="mb-4">
          <b-card
            no-body
            class="border-0 shadow-sm sticky-top"
            style="top: 90px"
          >
            <div class="p-3 bg-mbr-green text-white rounded-top">
              <h6 class="mb-0 font-weight-bold">
                <b-icon icon="gear-fill" class="mr-2"></b-icon>Configurações
              </h6>
            </div>
            <b-list-group flush class="settings-menu">
              <b-list-group-item
                button
                :class="{ active: selectedPanel === 1 }"
                @click="selectPanel(1)"
                class="d-flex align-items-center border-0"
              >
                <b-icon icon="people-fill" class="mr-3"></b-icon> Gestão de
                Usuários
              </b-list-group-item>

              <b-list-group-item
                button
                :class="{ active: selectedPanel === 4 }"
                @click="selectPanel(4)"
                class="d-flex align-items-center border-0"
              >
                <b-icon icon="credit-card-fill" class="mr-3"></b-icon> Contas
                Bancárias
              </b-list-group-item>

              <b-list-group-item
                button
                :class="{ active: selectedPanel === 2 }"
                @click="selectPanel(2)"
                class="d-flex align-items-center border-0"
              >
                <b-icon icon="percent" class="mr-3"></b-icon> Taxas e
                Financiamento
              </b-list-group-item>

              <b-list-group-item
                button
                :class="{ active: selectedPanel === 3 }"
                @click="selectPanel(3)"
                class="d-flex align-items-center border-0"
              >
                <b-icon icon="building" class="mr-3"></b-icon> Dados da
                Instituição
              </b-list-group-item>
            </b-list-group>
          </b-card>
        </b-col>

        <b-col lg="9" md="8">
          <transition name="fade" mode="out-in">
            <b-card
              border-variant="white"
              class="shadow-sm border-0 rounded-lg min-vh-75"
              :key="selectedPanel"
            >
              <UserComponent v-if="selectedPanel === 1" />
              <InterestRateComponent v-if="selectedPanel === 2" />
              <CompanyDetailsComponent v-if="selectedPanel === 3" />
              <AccountsComponent v-if="selectedPanel === 4" />
            </b-card>
          </transition>
        </b-col>
      </b-row>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";

import NavBarVue from "@/components/NavBar";
import UserComponent from "@/components/settings/UserComponent";
import InterestRateComponent from "@/components/settings/InterestRateComponent";
import CompanyDetailsComponent from "@/components/settings/CompanyDetailsComponent";
import AccountsComponent from "@/components/settings/AccountsComponent";

export default {
  data: () => ({
    selectedPanel: 1,
  }),

  computed: {
    ...mapGetters(["user", "token", "company", "updatedPassword"]),
  },

  created() {
    this.checkPasswordStatus();
  },

  components: {
    NavBarVue,
    UserComponent,
    InterestRateComponent,
    CompanyDetailsComponent,
    AccountsComponent,
  },

  methods: {
    selectPanel(panel) {
      if (panel === 1) {
        this.selectedPanel = 1;
      } else if (panel === 2) {
        this.selectedPanel = 2;
      } else if (panel === 3) {
        this.selectedPanel = 3;
      } else if (panel === 4) {
        this.selectedPanel = 4;
      }
    },

    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },
  },
};
</script>

<style scoped>
.bg-mbr-green {
  background-color: #009640 !important;
}

.settings-menu .list-group-item {
  color: #555;
  font-weight: 500;
  padding: 1rem 1.25rem;
  transition: all 0.2s ease;
}

.settings-menu .list-group-item:hover {
  background-color: #f8fdf9;
  color: #009640;
}

.settings-menu .list-group-item.active {
  background-color: #f0f9f4;
  color: #009640;
  border-left: 4px solid #009640 !important;
  font-weight: bold;
}

.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s;
}
.fade-enter,
.fade-leave-to {
  opacity: 0;
}
</style>
